/**
 * Error overlay — shows uncaught JS errors and unhandled promise rejections
 * in a visible overlay so the user sees them inside the task pane.
 *
 * Extracted from taskpane.html into its own file so the CSP can use
 * script-src 'self' without 'unsafe-inline'.
 */

(function (): void {
  var overlay = document.getElementById("error-overlay");
  var text = document.getElementById("error-overlay-text");

  function showError(msg: string): void {
    if (overlay && text) {
      text.textContent = msg;
      overlay.style.display = "block";
    }
  }

  window.addEventListener("error", function (e: ErrorEvent) {
    showError(e.error && e.error.stack ? e.error.stack : e.message || String(e));
  });

  window.addEventListener("unhandledrejection", function (e: PromiseRejectionEvent) {
    var reason = e.reason;
    showError(
      "Unhandled promise rejection:\n" +
        (reason && reason.stack ? reason.stack : reason && reason.message ? reason.message : String(reason))
    );
  });
})();
